def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "pick_up_pan": And([
            self.pan_at(self.pan, self.stove),
            Not(self.pan_cool(self.pan)),
            self.pan_just_used,
            Not(self.robot_has_heat_resistant_gripper)
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
